WITH with_latest AS (SELECT s.*, x.employee_salary FROM departments s JOIN LATERAL (SELECT c.salary AS employee_salary FROM employees c WHERE c.dept_id = s.id ORDER BY c.salary DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT id, location, budget, employee_salary, CASE WHEN location RLIKE '^(Chiang Mai|Singapore)$' THEN 'GROUP_A' WHEN location RLIKE '^(Bangkok|New York)$' THEN 'CORE' ELSE 'EXTENDED' END AS location_zone FROM with_latest ORDER BY employee_salary DESC NULLS FIRST;
